package com.nthexperience.desktop;

import android.app.*;
import android.content.*;
import android.graphics.*;
import android.os.*;
import android.view.*;
import android.widget.*;
import java.io.*;
import java.util.concurrent.*;
import org.json.*;

/** Real pointer gestures, retained drag views, persisted placement, and actionable Weather states. */
public final class EightGestureSmoke extends Instrumentation {
    MainActivity home;View root;DesktopStore store;EightStartScreen start;long down;
    public void onCreate(Bundle args){super.onCreate(args);start();}
    public void onStart(){Bundle result=new Bundle();try{
        store=new DesktopStore(getTargetContext());EightDefaults.initialize(store);store.prefs.edit().putInt("startup_mode",2).putBoolean("welcome_on_start",false).putBoolean("reduce_motion",true).commit();getTargetContext().getSharedPreferences(StorageAccess.PREFS,0).edit().putBoolean("seen",true).commit();getTargetContext().getSharedPreferences(StartupExperience.SESSION,0).edit().putBoolean("seen",true).putBoolean("welcome_seen",true).putBoolean(StartupExperience.HOME_OFFERED,true).commit();
        home=(MainActivity)startActivitySync(new Intent(Intent.ACTION_MAIN).setComponent(new ComponentName(getTargetContext(),MainActivity.class)).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));root=home.getWindow().getDecorView();waitForIdleSync();
        for(EightProfile profile:EightProfile.values()){
            ui(()->{home.open("@settings");EightSmoke.description(root,"Use "+profile.label+" shell").performClick();home.open("@desktop");home.open("@start");start=EightSmoke.find(root,EightStartScreen.class);start.data.name(null,"Drag destination");start.refreshHome();});SystemClock.sleep(350);waitForIdleSync();
            HorizontalScrollView[] retained={start.horizontal};View source=EightSmoke.description(start,"Desktop, Wide Start tile");Rect r=bounds(source),viewport=bounds(start.viewport);float x=r.centerX(),y=r.centerY();
            down=SystemClock.uptimeMillis();pointer(MotionEvent.ACTION_DOWN,x,y);SystemClock.sleep(ViewConfiguration.getLongPressTimeout()+180);pointer(MotionEvent.ACTION_MOVE,x+24,y);SystemClock.sleep(180);pointer(MotionEvent.ACTION_MOVE,viewport.right-8,y);SystemClock.sleep(1500);waitForIdleSync();
            ui(()->{check(start.horizontal==retained[0],"Drag retains the same horizontal viewport");check(source.isAttachedToWindow()&&source.getAlpha()<1,"Native source stays attached during drag");check(start.horizontal.getScrollX()>100,"Holding tile at right edge scrolls across columns");start.refreshHome();check(start.horizontal==retained[0],"Appearance refresh defers rebuilding during drag");});shot("eight4-drag-"+profile.id);
            pointer(MotionEvent.ACTION_MOVE,viewport.right-40,y);pointer(MotionEvent.ACTION_UP,viewport.right-40,y);SystemClock.sleep(450);waitForIdleSync();
            ui(()->{EightStartData saved=new EightStartData(store,profile);check(saved.groups.get(saved.groups.size()-1).items.stream().anyMatch(i->i.id.equals("@desktop")),"Actual cross-screen drop persists in the last group");check(saved.groups.stream().flatMap(g->g.items.stream()).filter(i->i.id.equals("@desktop")).count()==1,"Drop never duplicates a tile");});
            // Drag in the reverse direction, then cancel: neither ordering nor scroll views should jump.
            String layout=store.prefs.getString(EightStartData.key(profile),"");View moved=EightSmoke.description(start,"Desktop, Wide Start tile");r=bounds(moved);down=SystemClock.uptimeMillis();pointer(MotionEvent.ACTION_DOWN,r.centerX(),r.centerY());SystemClock.sleep(ViewConfiguration.getLongPressTimeout()+150);pointer(MotionEvent.ACTION_MOVE,r.centerX()-24,r.centerY());pointer(MotionEvent.ACTION_MOVE,viewport.left+8,r.centerY());SystemClock.sleep(1000);ui(()->{check(start.horizontal.getScrollX()<100,"Left-edge drag scrolls back to earlier groups");moved.cancelDragAndDrop();});pointer(MotionEvent.ACTION_UP,viewport.left+8,r.centerY());SystemClock.sleep(300);check(layout.equals(store.prefs.getString(EightStartData.key(profile),"")),"Cancelling a drag preserves saved ordering");
            for(boolean apps:new boolean[]{false,true}){ui(()->{home.open("@desktop");home.open(apps?"@allapps":"@start");});SystemClock.sleep(180);Rect area=bounds(start.viewport);swipe(area.centerX(),area.top+50,area.centerX(),Math.min(area.bottom-30,area.top+300));ui(()->check(!start.isShown(),"Downward swipe returns "+(apps?"Apps":"Start")+" to Desktop"));}
            ui(()->{home.open("@start");});SystemClock.sleep(150);Rect area=bounds(start.viewport);swipe(area.right-25,area.centerY(),area.left+25,area.centerY());ui(()->check(start.isShown(),"Horizontal panning keeps Start open"));
        }
        ui(()->{home.open("@desktop");home.open("@control");check(EightSmoke.find(root,VistaControlPanel.class).isShown(),"Control Panel shortcut opens traditional categories");check(!EightSmoke.find(root,EightPCSettings.class).isShown(),"Control Panel is separate from PC settings");});shot("eight4-control-panel");
        ui(()->{home.openEightTile("@weather");WeatherPanel weather=EightSmoke.find(root,WeatherPanel.class);check(EightSmoke.description(weather,"Weather city search").isShown(),"Empty Weather exposes setup immediately");check(EightSmoke.description(weather,"Weather My location").isShown()&&EightSmoke.description(weather,"Weather Refresh").isShown(),"Weather actions need no ellipsis");});shot("eight4-weather-empty");
        String weatherJson="{\"properties\":{\"timeseries\":[{\"time\":\"2026-11-06T18:00:00Z\",\"data\":{\"instant\":{\"details\":{\"air_temperature\":12}},\"next_1_hours\":{\"summary\":{\"symbol_code\":\"rain\"}}}}]}}";
        ui(()->{store.prefs.edit().putString("weather_lat","40.0").putString("weather_lon","-75.0").putString("weather_city","Weather test city").putString("weather_json",weatherJson).putBoolean("weather_f",false).putLong("weather_updated",System.currentTimeMillis()).putLong("weather_expires",System.currentTimeMillis()+3600000).commit();home.open("@desktop");home.open("@start");check(EightAuditSmoke.texts(start).contains("12°")&&EightAuditSmoke.texts(start).contains("Rain"),"Live tile shows cached actual temperature and condition");});shot("eight4-weather-tile");
        java.lang.reflect.Field serviceField=MainActivity.class.getDeclaredField("services");serviceField.setAccessible(true);TenServices services=(TenServices)serviceField.get(home);java.lang.reflect.Field snapshotField=WeatherClient.class.getDeclaredField("snapshot");snapshotField.setAccessible(true);snapshotField.set(services.weather,WeatherClient.Snapshot.parse(weatherJson));
        ui(()->{home.openEightTile("@weather");WeatherPanel actual=EightSmoke.find(root,WeatherPanel.class);actual.refresh();EightSmoke.description(actual,"Weather Places").performClick();actual.scrollTo(0,0);check(EightAuditSmoke.texts(actual).contains("12°C"),"Launched Weather shows cached temperature");});shot("eight4-weather-forecast");
        // A new client reads the real cache parser, without depending on an external weather service.
        ui(()->{WeatherClient client=new WeatherClient(store,()->{});WeatherLocation location=new WeatherLocation(home,store,client,()->true,()->{});WeatherPanel panel=new WeatherPanel(home,store,client,location,new WeatherPanel.Host(){public void locate(){}public void settings(){}public void follow(boolean v){}public void refresh(){}});panel.immersive(true,false);check(EightAuditSmoke.texts(panel).contains("12°C")&&EightAuditSmoke.texts(panel).contains("Rain"),"Weather hero displays parsed condition and correct Celsius value");check(EightSmoke.description(panel,"Weather city search").getVisibility()==View.VISIBLE&&EightSmoke.description(panel,"Weather Places settings").getVisibility()==View.GONE,"Configured forecast keeps Places expandable");panel.immersive(true,true);check(EightSmoke.description(panel,"Weather Places settings").getVisibility()==View.VISIBLE,"App commands also reach Places");panel.close();client.close();});
        result.putString("stream","PASS: native hold-and-drag autoscrolls right and left in both profiles; source/viewport retained through deferred refresh; successful drop persisted once; cancellation preserved ordering; Start and All Apps down-swipes return Desktop; horizontal panning preserved; traditional Control Panel route; empty Weather visible actions; live tile and forecast actual parsed temperature and condition\n");finish(Activity.RESULT_OK,result);
    }catch(Throwable failure){try{shot("eight4-failure");}catch(Exception ignored){}result.putString("stream","FAIL: "+android.util.Log.getStackTraceString(failure));finish(Activity.RESULT_CANCELED,result);}}
    void ui(Runnable r)throws Exception{FutureTask<Void> t=new FutureTask<>(r,null);home.runOnUiThread(t);t.get(20,TimeUnit.SECONDS);waitForIdleSync();}
    void check(boolean value,String label){if(!value)throw new AssertionError(label);}
    Rect bounds(View v){check(v!=null,"Gesture target exists");Rect r=new Rect();check(v.getGlobalVisibleRect(r),"Gesture target visible: "+v.getContentDescription());return r;}
    void pointer(int action,float x,float y){MotionEvent.PointerProperties prop=new MotionEvent.PointerProperties();prop.id=0;prop.toolType=MotionEvent.TOOL_TYPE_FINGER;MotionEvent.PointerCoords point=new MotionEvent.PointerCoords();point.x=x;point.y=y;point.pressure=1;point.size=1;MotionEvent e=MotionEvent.obtain(down,SystemClock.uptimeMillis(),action,1,new MotionEvent.PointerProperties[]{prop},new MotionEvent.PointerCoords[]{point},0,0,1,1,0,0,InputDevice.SOURCE_TOUCHSCREEN,0);check(getUiAutomation().injectInputEvent(e,true),"Pointer injection reaches native drag consumer");e.recycle();}
    void swipe(float x,float y,float toX,float toY){down=SystemClock.uptimeMillis();pointer(MotionEvent.ACTION_DOWN,x,y);for(int i=1;i<=12;i++){SystemClock.sleep(16);pointer(MotionEvent.ACTION_MOVE,x+(toX-x)*i/12,y+(toY-y)*i/12);}pointer(MotionEvent.ACTION_UP,toX,toY);waitForIdleSync();}
    void shot(String name)throws Exception{waitForIdleSync();SystemClock.sleep(160);Bitmap b=getUiAutomation().takeScreenshot();boolean blank=b==null;if(b!=null){blank=true;for(int y=0;y<b.getHeight()&&blank;y+=24)for(int x=0;x<b.getWidth();x+=24)if((b.getPixel(x,y)&0xffffff)!=0){blank=false;break;}}if(blank){if(b!=null)b.recycle();b=Bitmap.createBitmap(root.getWidth(),root.getHeight(),Bitmap.Config.ARGB_8888);Bitmap out=b;ui(()->root.draw(new Canvas(out)));name+="-view";}try(OutputStream out=new FileOutputStream(new File(getTargetContext().getFilesDir(),name+".png"))){b.compress(Bitmap.CompressFormat.PNG,100,out);}finally{b.recycle();}}
}
